// Response, error and event types that pages import. Response types re-export the components of
// src/api/schema.d.ts (generated by npm run gen:api); error and event types follow contracts/studio-api.md.

import type { components } from './schema';

export type KnownErrorCode =
  | 'not_signed_in'
  | 'validation_failed'
  | 'run_refused'
  | 'estimate_too_large'
  | 'publish_refused'
  | 'not_found'
  | 'conflict'
  | 'out_of_date'
  // Made by the client: the server could not be reached, or something in between answered without an error body.
  | 'network_error';

export interface Problem {
  code: string;
  message: string;
  block?: string | null;
  location_mm?: number[] | null;
  severity?: string | null;
}

export interface MissingItem {
  item: string;
  message: string;
}

export interface ErrorBody {
  code: string;
  message: string;
  problems: Problem[];
  missing: MissingItem[];
}

// Responses: generated from the server's OpenAPI document (npm run gen:api).

type Schemas = components['schemas'];

export type LoginRequest = Schemas['LoginRequest'];
export type LoginResponse = Schemas['LoginResult'];
export type SessionInfo = Schemas['SessionInfo'];
export type LaneCounts = Schemas['LaneCounts'];
export type MemoryInfo = Schemas['MemoryInfo'];
export type DiskInfo = Schemas['DiskInfo'];
export type SystemInfo = Schemas['SystemInfo'];
export type ConventionsInfo = Schemas['ConventionsInfo'];

// Server-Sent Events (GET /api/events)

export type StudioEventType =
  | 'preview.ready'
  | 'run.progress'
  | 'run.finished'
  | 'study.progress'
  | 'job.failed'
  | 'validity.changed'
  | 'capability.changed';

export interface RunProgressEvent {
  run_id: string;
  percent: number;
  stage: string;
  remaining_s: number | null;
}

// Only run.progress has a fixed shape in the contract; the pages that use the others narrow them.
export type GenericEventData = Record<string, unknown>;

export interface StudioEventDataMap {
  'preview.ready': GenericEventData;
  'run.progress': RunProgressEvent;
  'run.finished': GenericEventData;
  'study.progress': GenericEventData;
  'job.failed': GenericEventData;
  'validity.changed': GenericEventData;
  'capability.changed': GenericEventData;
}

