/** One setting in a block's settings schema (GET /api/blocks): JSON Schema plus `group`, `kind` and units. */
export interface SettingSchema {
  title: string;
  group: string;
  kind: 'design' | 'library';
  type: 'number' | 'integer' | 'boolean' | 'string' | 'array';
  items?: { type: 'string' | 'number' };
  minItems?: number;
  maxItems?: number;
  unit?: string;
  default?: unknown;
  minimum?: number;
  maximum?: number;
  exclusiveMinimum?: number;
  exclusiveMaximum?: number;
  enum?: string[];
  parameter_key?: string;
  description?: string;
}

export interface BlockTypeEntry {
  type_id: string;
  version: string;
  slice: string;
  label: string;
  description: string;
  settings_schema: {
    title: string;
    properties: Record<string, SettingSchema>;
    required: string[];
    groups: { id: string; label: string }[];
  };
  /** `capacity`: how many blocks each socket holds (one for every socket so far). A keyed attach point
   * (`keys_from`, a string-list design setting) is offered once per value of that setting, as `<name>:<value>`;
   * a bare `<name>` means the key in the design setting `default_key_from`. */
  attach_points: {
    name: string;
    label: string;
    description: string;
    capacity?: number;
    keys_from?: string | null;
    default_key_from?: string | null;
  }[];
  attaches_to: string[];
  needs_physics: string[];
  result_types: {
    id: string;
    label: string;
    regions: string[];
    needs_physics: string[];
    status: 'ready' | 'awaiting_benchmark';
    locked_message: string | null;
  }[];
  report_regions: string[];
  status: 'ready' | 'awaiting_benchmark';
  awaiting: string[];
}

export interface QueueItem {
  id: string;
  lane: 'heavy' | 'preview';
  kind: string;
  target_id: string | null;
  position: number;
  status: string;
  created_at: string;
  started_at: string | null;
  finished_at?: string | null;
  failure_reason?: string | null;
  run?: {
    scenario_id: string | null;
    detail_level: string;
    estimate: { dof: number; time_s: number; memory_gb: number; disk_gb: number } | null;
    name: string;
  };
}

export interface QueueView {
  heavy: QueueItem[];
  preview: QueueItem[];
  /** The latest finished jobs other than previews, newest first. */
  recent: QueueItem[];
}
export type NamedPoint = Schemas['NamedPoint'];
